@partial(jit, static_argnums=0)        
def Visa(self,
          Xisa:jnp.ndarray, # Joint strategy
          ) -> jnp.ndarray:  # Average state-action values
    """
    Compute Q-value for state `s` and action `a`.
    """
    Visav = self.Visav(Xisa)  # Q-value distrib
    gpoints = jnp.ones((self.nr)) * -1
    gpoints = gpoints.at[:].set(self.gridpoints)
    Visa = jnp.einsum('ijkl,l->ijk', Visav, gpoints)
    i = 0; a = 1; s = 2
    Vis = jnp.einsum(Visa, [i, s, a], Xisa, [i, s, a], [i, s])
    # Baseline: mean of Qisaq
    Vis_expanded = jnp.expand_dims(Vis, axis=2)  # shape (N, Z, 1)
    baseline = jnp.repeat(Vis_expanded, self.M, axis=2)  # shape (N, Z, M)
    if self.method=='mean':  # take mean
        return Visa
    elif self.method=='quantile':  # use quantile
        return quantile(self.tau, Visav, gpoints)
    elif self.method=='expectile':  # use expectile
        return expectile(self.tau, Visav, gpoints)
    elif self.method=='weights':  # use weights
        w = jnp.ones((self.N, self.Z, self.M, len(self.gridpoints)))
        n = jnp.newaxis
        upper = self.gridpoints[n,n,n,:] >= baseline[:,:,:,n]
        upper = upper * (self.wU - 1)
        w = w + upper
        wVisav = weights(w, Visav, gpoints)
        Visa = jnp.einsum('ijkl,l->ijk', wVisav, gpoints)  # take the new distrib's mean
        return Visa

DDRLActorCritic.Visa = Visa 

# %% ../../nbs/02.03_DDRLActorCritic.ipynb 14
@partial(jit, static_argnums=(0,2))
def TDerror(self:DDRLActorCritic,
            Xisa,  # Behavior profiles
            norm=False) -> jnp.ndarray:
    """
    Compute reward-prediction/temporal-difference error for 
    strategy actor-critic dynamics, given joint strategy `Xisa`.
    """
    V = self.Visa(Xisa)
    n = jnp.newaxis
    E = V
    E *= self.beta[:,n,n]

    E = E - E.mean(axis=2, keepdims=True) if norm else E
    return E

DDRLActorCritic.TDerror = TDerror
